mapper.update:
UPDATE iam_resource_share
SET status = #{status}, active_slot = NULL, revoke_reason = #{reason},
    revoked_by = NULL, revoked_at = #{now}, version = version + 1, updated_at = #{now}
WHERE tenant_id = #{tenantId} AND id = #{shareId} AND version = #{expectedVersion}

mapper.select:
SELECT epoch
FROM iam_share_projection_epoch
WHERE tenant_id = #{tenantId} AND resource_id = #{resourceId}
